// SIMPLE HASH FUNCTION for strings
function simpleHash(key, arraySize) {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
        hash = (hash * 31 + key.charCodeAt(i)) % arraySize;
        // 31 is a prime — primes reduce collision clustering
    }
    return hash; // always in range [0, arraySize-1]
}

console.log(simpleHash('apple', 10));  // e.g. 3
console.log(simpleHash('apple', 10));  // 3 — deterministic: always same output
console.log(simpleHash('appld', 10));  // e.g. 8 — avalanche: one char change, big difference

// WHY PRIME MULTIPLIERS HELP
// Using 31 (prime) spreads bits more uniformly than 32 (power of 2)
// Power-of-2 multipliers cause periodic patterns in lower bits
// Primes break periodicity → better distribution → fewer collisions

// O(1) AVERAGE: what this means in practice
// Array of size 1000, inserting 500 items with uniform distribution:
// Expected items per slot: 0.5 → average lookup: 0.5 steps → O(1)

// O(n) WORST CASE: what can go wrong
// If simpleHash maps 'a','b','c','d' all to index 5:
// Looking up 'e' at index 5 means scanning all 4 existing items first
// This is why collision handling matters (Lesson 4)

// AVALANCHE EFFECT TEST
console.log(simpleHash('hello', 100));   // e.g. 47
console.log(simpleHash('hellp', 100));   // e.g. 78 — one char different = very different hash
console.log(simpleHash('helo', 100));    // e.g. 12 — shorter string = very different hash

