// SEPARATE CHAINING — manual implementation
class HashMapChaining {
    constructor(size = 10) {
        this.buckets = new Array(size).fill(null).map(() => []);
        this.size = size;
        this.count = 0;
    }
    _hash(key) {
        let h = 0;
        for (const c of String(key)) h = (h * 31 + c.charCodeAt(0)) % this.size;
        return h;
    }
    set(key, value) {
        const idx = this._hash(key);
        const bucket = this.buckets[idx];
        const existing = bucket.find(([k]) => k === key);
        if (existing) existing[1] = value;  // update existing
        else { bucket.push([key, value]); this.count++; } // new entry
        // Auto-resize when load factor > 0.75
        if (this.count / this.size > 0.75) this._resize();
    }
    get(key) {
        const bucket = this.buckets[this._hash(key)];
        return bucket.find(([k]) => k === key)?.[1];
    }
    has(key) { return this.get(key) !== undefined; }
    _resize() {
        const oldBuckets = this.buckets;
        this.size *= 2;  // double capacity
        this.buckets = new Array(this.size).fill(null).map(() => []);
        this.count = 0;
        for (const bucket of oldBuckets)
            for (const [k, v] of bucket) this.set(k, v); // rehash all entries
    }
}

