// TWO SUM — single pass hash map: O(n) time, O(n) space
function twoSum(nums, target) {
    const seen = new Map(); // value → index
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (seen.has(complement)) {
            return [seen.get(complement), i];
        }
        seen.set(nums[i], i);
    }
    return [];
}
// [2,7,11,15] target=9:
// i=0: complement=7, not in seen → add {2:0}
// i=1: complement=2, IN SEEN at 0 → return [0,1]

// TWO SUM II (sorted input): two pointers — O(n) time, O(1) space
function twoSumSorted(nums, target) {
    let left = 0, right = nums.length - 1;
    while (left < right) {
        const sum = nums[left] + nums[right];
        if (sum === target) return [left + 1, right + 1]; // 1-indexed
        if (sum < target) left++;
        else right--;
    }
}
// When to use which:
// Unsorted input → hash map (O(n) time, O(n) space)
// Sorted input   → two pointers (O(n) time, O(1) space) ← strictly better

// THREE SUM — sort + two pointers: O(n²) time, O(1) space
function threeSum(nums) {
    nums.sort((a, b) => a - b);
    const result = [];
    for (let i = 0; i < nums.length - 2; i++) {
        if (i > 0 && nums[i] === nums[i-1]) continue; // skip outer duplicates
        let left = i + 1, right = nums.length - 1;
        while (left < right) {
            const sum = nums[i] + nums[left] + nums[right];
            if (sum === 0) {
