function topKFrequent_sort(nums, k) {
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
    return [...freq.entries()]
        .sort((a, b) => b[1] - a[1]) // sort by frequency descending
        .slice(0, k)
        .map(([num]) => num);
}

// APPROACH 2: Bucket Sort — O(n) time, O(n) space
function topKFrequent_bucket(nums, k) {
    // Step 1: build frequency map O(n)
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);

    // Step 2: create n+1 buckets indexed by frequency
    // bucket[i] = list of elements appearing exactly i times
    // Max frequency = nums.length, so bucket index goes from 0 to n
    const buckets = new Array(nums.length + 1).fill(null).map(() => []);
    for (const [num, count] of freq) {
        buckets[count].push(num); // element num appears 'count' times
    }

    // Step 3: collect k elements from highest-frequency buckets downward
    const result = [];
    for (let i = buckets.length - 1; i >= 1 && result.length < k; i--) {
        result.push(...buckets[i]);
    }
    return result.slice(0, k);
}

