// VALID SUDOKU — three arrays of Sets: O(81) = O(1) time and space
function isValidSudoku(board) {
    const rows  = Array.from({length: 9}, () => new Set());
    const cols  = Array.from({length: 9}, () => new Set());
    const boxes = Array.from({length: 9}, () => new Set());

    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const val = board[r][c];
            if (val === '.') continue; // empty cell — skip

            // Box index maps (r,c) to one of 9 boxes:
            // (0-2, 0-2)→0  (0-2, 3-5)→1  (0-2, 6-8)→2
            // (3-5, 0-2)→3  (3-5, 3-5)→4  (3-5, 6-8)→5
            // (6-8, 0-2)→6  (6-8, 3-5)→7  (6-8, 6-8)→8
            const boxIdx = Math.floor(r / 3) * 3 + Math.floor(c / 3);

            if (rows[r].has(val) || cols[c].has(val) || boxes[boxIdx].has(val)) {
                return false; // duplicate found in row, col, or box
            }
            rows[r].add(val);
            cols[c].add(val);
            boxes[boxIdx].add(val);
        }
    }
    return true;
}

// ALTERNATIVE: single Set with composite string keys — more compact
function isValidSudoku_oneSet(board) {
    const seen = new Set();
    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const val = board[r][c];
            if (val === '.') continue;
            const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
            // Three composite keys — one per constraint
            const rKey = `r${r}:${val}`;
            const cKey = `c${c}:${val}`;
            const bKey = `b${boxIdx}:${val}`;
            if (seen.has(rKey) || seen.has(cKey) || seen.has(bKey)) return false;
            seen.add(rKey); seen.add(cKey); seen.add(bKey);
        }
    }
    return true;
}

