function isValidSudokuImpl(board) {
  const rows = Array.from({length: 9}, () => new Set());
  const cols = Array.from({length: 9}, () => new Set());
  const boxes = Array.from({length: 9}, () => new Set());
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const val = board[r][c];
      if (val === '.') continue;
      const boxIdx = Math.floor(r / 3) * 3 + Math.floor(c / 3);
      if (rows[r].has(val) || cols[c].has(val) || boxes[boxIdx].has(val)) {
        return false;
      }
      rows[r].add(val);
      cols[c].add(val);
      boxes[boxIdx].add(val);
    }
  }
  return true;
}

function isValidSudokuOneSetImpl(board) {
  const seen = new Set();
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const val = board[r][c];
      if (val === '.') continue;
      const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
      const rKey = `r${r}:${val}`;
      const cKey = `c${c}:${val}`;
      const bKey = `b${boxIdx}:${val}`;
      if (seen.has(rKey) || seen.has(cKey) || seen.has(bKey)) return false;
      seen.add(rKey); seen.add(cKey); seen.add(bKey);
    }
  }
  return true;
}

function verifyBothApproachesAgree(board) {
  return isValidSudokuImpl(board) === isValidSudokuOneSetImpl(board);
}

