// Valid Anagram: FREQUENCY COUNTER
function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i)-97]++;
        count[t.charCodeAt(i)-97]--;
    }
    return count.every(c => c === 0);
} // O(n) time, O(1) space

// Two Sum: COMPLEMENT LOOKUP
function twoSum(nums, target) {
    const seen = new Map();
    for (let i = 0; i < nums.length; i++) {
        const c = target - nums[i];
        if (seen.has(c)) return [seen.get(c), i];
        seen.set(nums[i], i);
    }
} // O(n) time, O(n) space

// Longest Consecutive: SEEN SET
function longestConsecutive(nums) {
    const s = new Set(nums); let max = 0;
    for (const n of s) if (!s.has(n-1)) {
        let cur=n, len=1;
        while(s.has(cur+1)){cur++;len++;}
        max=Math.max(max,len);
    }
    return max;
} // O(n) time, O(n) space

// Top K Frequent: FREQUENCY COUNTER + BUCKET SORT
function topKFrequent(nums, k) {
    const freq=new Map(); for(const n of nums) freq.set(n,(freq.get(n)||0)+1);
    const buckets=new Array(nums.length+1).fill(null).map(()=>[]);
    for(const [n,c] of freq) buckets[c].push(n);
    const res=[]; for(let i=buckets.length-1;i>=1&&res.length<k;i--) res.push(...buckets[i]);
    return res.slice(0,k);
} // O(n) time, O(n) space

