// RECOGNITION SIGNALS:
// Frequency Counter: count occurrences, k most frequent, check equal frequencies
// Complement Lookup: find pair/triple summing to a target
// Seen Set: duplicate detection, cycle detection, visited tracking
// Fingerprinting: group by equivalence, items sharing a hidden property
// HASH MAP DOES NOT HELP WHEN: sorted order is specifically needed, O(1) space is
// strictly required, or spatial locality matters (arrays keep related data physically close)

function classifyHashMapPattern(signals) {
  const s = new Set(signals);
  if (s.has('sorted_order_required') || s.has('o1_space_required') || s.has('spatial_locality')) {
    return 'Hash Map Not Applicable';
  }
  if (s.has('count_occurrences')) return 'Frequency Counter';
  if (s.has('pair_sum_target')) return 'Complement Lookup';
  if (s.has('duplicate_detection')) return 'Seen Set';
  if (s.has('group_by_equivalence')) return 'Fingerprinting';
  return 'Unknown';
}

function solveFrequencyCounter(s) {
  const freq = new Map();
  for (const c of s) freq.set(c, (freq.get(c) || 0) + 1);
  return freq;
}

function solveComplementLookup(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}

function solveSeenSet(nums) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(n)) return true;
    seen.add(n);
  }
  return false;
}

function solveFingerprinting(strs) {
  const map = new Map();
  for (const str of strs) {
    const count = new Array(26).fill(0);
    for (const c of str) count[c.charCodeAt(0) - 97]++;
    const key = count.join('#');
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(str);
  }
  return [...map.values()];
}

function runFullSuite() {
  return {
    frequencyCounter: solveFrequencyCounter('hello').size > 0,
    complementLookup: solveComplementLookup([2,7,11,15], 9).length === 2,
    seenSet: typeof solveSeenSet([1,2,3,2]) === 'boolean',
    fingerprinting: solveFingerprinting(['eat','tea']).length > 0
  };
}
